"""Remove unreferenced intermediate images generated by this archive import."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ASSETS = (ROOT / 'public/pmerj-arquivo').resolve()
assert ASSETS.is_relative_to(ROOT.resolve() / 'public')
exams = json.loads((ROOT / 'pdf-extracts/pmerj-ate-2020/importacao.json').read_text(encoding='utf-8'))
used = {Path(image).name for exam in exams for q in exam['questions'] for image in json.loads(q['support_image'] or '[]')}
removed = 0
for path in ASSETS.glob('pmerj-*.png'):
    assert path.resolve().parent == ASSETS
    if path.name not in used:
        path.unlink()
        removed += 1
print(f'{len(used)} referenced images retained; {removed} intermediate generated images removed.')
